/** The keychain uses two maroons for the four disc tones. */
export function keychainYarnKey(c: string): string {
  if (c === "1" || c === "2") return "D";
  if (c === "3" || c === "4") return "P";
  return c;
}

export type LegendEntry = {
  key: string;
  color: string;
  ink: string;
  name: string;
};

